sqlMap.insert:
INSERT INTO DebitNotes (Id, ContractId, PeriodYear, PeriodMonth, BillNo, DueDate,
  TotalAmount, TotalReceived, Status, GeneratedAt, GeneratedBy, IsHistorical, CompanyId, CreatedBy, CreatedAt,
  ContractNo, TenantName, BuildingAddress, CompanyName, PreviousBalance)
  VALUES (@Id, @ContractId, @PeriodYear, @PeriodMonth, @BillNo, @DueDate,
  @TotalAmount, 0, 'Published', DATEADD(HOUR, 8, GETUTCDATE()), @GeneratedBy, 0, @CompanyId, @CreatedBy, DATEADD(HOUR, 8, GETUTCDATE()),
  @ContractNo, @TenantName, @BuildingAddress, @CompanyName, @PreviousBalance)

INSERT INTO DebitNotes (Id, BillNo, ContractId, PeriodYear, PeriodMonth, CompanyId,
  TotalAmount, TotalReceived, IsHistorical, DueDate, Status, GeneratedAt, GeneratedBy, CreatedBy, CreatedAt,
  ContractNo, TenantName, BuildingAddress, CompanyName, PreviousBalance)
  VALUES (@Id, @NoteNo, @CId, @PeriodYear, @PeriodMonth, @CoId,
  @Amt, 0, @IsHist, @Due, 'Published', DATEADD(HOUR, 8, GETUTCDATE()), @CBy, @CBy, DATEADD(HOUR, 8, GETUTCDATE()),
  @ContractNo, @TenantName, @BuildingAddress, @CompanyName, @PreviousBalance)

    INSERT INTO Journals (Id, CompanyId, ContractId, FeeCodeId, FeeConfigId,
      AccountingSubjectId, Period, Amount, DueDate, EntryType, GLPosted, BilledAt, BillMonth,
      DebitNoteId, ParentJournalId, Summary, CreatedBy, CreatedAt)
      VALUES (@Id, @CoId, @CId, @FId, @FConfigId,
      @SubjId, @Period, @Amt, @Due, @EntryType, 1, @BilledAt,
	      @Period,
	      @DNId, @ParentId, @Summary, @CBy, DATEADD(HOUR, 8, GETUTCDATE()))

sqlMap.select:
    SELECT c.*, r.FullCode AS RoomFullCode FROM Contracts c LEFT JOIN HousingUnits r ON r.Id = c.RoomId WHERE c.Id = @Id;
SELECT ct.ContractId, ct.TenantId, t.Name AS TenantName, ct.IsPrimary FROM ContractTenants ct INNER JOIN Tenants t ON t.Id = ct.TenantId WHERE ct.ContractId = @Id;
SELECT cf.Id, cf.ContractId, cf.FeeCodeId, fc.Name AS FeeCodeName, fc.Code AS FeeCode, fc.ChargeType,
       cf.BillingMode, cf.Amount, cf.Unit, cf.UnitPrice, cf.IsActive, cf.EffectiveDate, cf.ExpiryDate
FROM ContractFeeConfigs cf LEFT JOIN FeeCodes fc ON fc.Id = cf.FeeCodeId WHERE cf.ContractId = @Id
